/* Generated bytes and mock Android storage only; no native/device process exists. */
const assert = require('assert');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const {
  load,
  enums,
  checkIf,
  log,
  transferHelpers,
} = require('./transfer-reliability.test');

const root = fs.mkdtempSync('/private/tmp/openmtp-cross-transfer-fixtures-');
const hash = (bytes) => crypto.createHash('sha256').update(bytes).digest('hex');
const tests = [];
const test = (name, run) => tests.push({ name, run });

for (const direction of ['upload', 'download'])
  for (const outcome of [
    'completed',
    'failed',
    'cancelled',
    'unknown',
    'missing',
    'lookup-error',
  ]) {
    test(`${direction} disposable ${outcome}: retain sources and classify destination evidence`, async () => {
      const own = fs.mkdtempSync(path.join(root, 'case-'));
      const sourceDir = path.join(own, 'source');
      const destinationDir = path.join(own, 'destination');

      fs.mkdirSync(sourceDir);
      fs.mkdirSync(destinationDir);
      const generated = Buffer.from(
        `OpenMTP generated fixture ${path.basename(own)} ${'safe bytes '.repeat(
          200
        )}`
      );
      const android = new Map();
      const localSource = path.join(sourceDir, 'fixture.bin');
      const androidSource = '/source/fixture.bin';

      fs.writeFileSync(localSource, generated);
      android.set(androidSource, Buffer.from(generated));
      const source = direction === 'upload' ? localSource : androidSource;
      const destination =
        direction === 'upload' ? '/destination' : destinationDir;
      const target =
        direction === 'upload'
          ? '/destination/fixture.bin'
          : path.join(destinationDir, 'fixture.bin');
      const calls = [];
      const notices = [];
      const safeLocal = (file) =>
        assert(file.startsWith(`${own}/`), 'Unexpected local path');
      const controller = load(
        'app/data/file-explorer/controllers/FileExplorerController.js',
        {
          path,
          '../repositories/FileExplorerRepository': {
            FileExplorerRepository: class {
              async transferFiles(args) {
                calls.push('payload');
                assert.strictEqual(args.direction, direction);
                assert.strictEqual(args.fileList.length, 1);
                const bytes =
                  direction === 'upload'
                    ? (safeLocal(args.fileList[0]),
                      fs.readFileSync(args.fileList[0]))
                    : android.get(args.fileList[0]);
                const output =
                  outcome === 'completed' || outcome === 'lookup-error'
                    ? bytes
                    : bytes.subarray(0, 32);

                if (outcome !== 'missing') {
                  if (direction === 'upload')
                    android.set(target, Buffer.from(output));
                  else {
                    safeLocal(target);
                    fs.writeFileSync(target, output);
                  }
                }

                return transferHelpers.createTransferResult({
                  status:
                    outcome === 'missing' || outcome === 'lookup-error'
                      ? 'completed'
                      : outcome,
                  backend: 'legacy',
                  direction,
                  backendStopped: outcome !== 'unknown',
                  evidence: {
                    exitCode: outcome === 'failed' ? 1 : 0,
                    signal: null,
                    cancellationAcknowledged: outcome === 'cancelled',
                  },
                  files: { requested: args.fileList },
                });
              }

              async filesExist(args) {
                calls.push('verify');
                assert.strictEqual(
                  args.deviceType,
                  direction === 'upload' ? 'mtp' : 'local'
                );
                assert.deepStrictEqual(Array.from(args.fileList), [target]);
                if (outcome === 'lookup-error')
                  throw new Error('Injected verification EIO');
                if (direction === 'upload') return android.has(target);
                safeLocal(target);

                return fs.existsSync(target);
              }
            },
          },
          '../../../utils/checkIf': { checkIf },
          '../../../services/analytics': {
            analyticsService: { sendEvent() {} },
          },
          '../../../enums/events': { EVENT_TYPE: {} },
          '../../../helpers/processBufferOutput': {},
          '../../../helpers/settings': { getMtpModeSetting: () => 'legacy' },
          '../../../enums': enums,
          '../../../utils/date': { unixTimestampNow: () => 1 },
          '../../../utils/log': { log },
          '../transferResult': transferHelpers,
        }
      ).default;
      const before = hash(generated);
      const result = await controller.transferFiles({
        deviceType: 'mtp',
        direction,
        destination,
        storageId: 1,
        fileList: [source],
        onError: (r) => notices.push(r),
        onCompleted: (r) => notices.push(r),
        onProgress() {},
        onPreprocess() {},
      });

      assert.strictEqual(notices.length, 1);
      assert.strictEqual(calls.filter((v) => v === 'payload').length, 1);
      assert.strictEqual(hash(fs.readFileSync(localSource)), before);
      assert.strictEqual(hash(android.get(androidSource)), before);
      if (outcome === 'completed') {
        assert.strictEqual(result.status, 'completed');
        assert.strictEqual(result.evidence.destinationPresence, 'confirmed');
        assert.strictEqual(result.evidence.contentVerified, false);
        const output =
          direction === 'upload'
            ? android.get(target)
            : fs.readFileSync(target);

        assert.strictEqual(hash(output), before);
      } else {
        assert.notStrictEqual(result.status, 'completed');
        assert.strictEqual(result.destinationMayContainPartialData, true);
        if (outcome !== 'missing')
          assert(
            direction === 'upload'
              ? android.has(target)
              : fs.existsSync(target),
            'Uncertain output was removed automatically'
          );
        if (['failed', 'cancelled', 'unknown'].includes(outcome))
          assert.strictEqual(calls.filter((v) => v === 'verify').length, 0);
      }
    });
  }

(async () => {
  let passed = 0;

  await tests.reduce(async (previous, { name, run }) => {
    await previous;
    try {
      await run();
      passed += 1;
      console.info(`PASS ${name}`);
    } catch (e) {
      console.error(`FAIL ${name}`, e);
      process.exitCode = 1;
    }
  }, Promise.resolve());
  console.info(
    `${passed}/${tests.length} cross-endpoint fixture tests passed.`
  );
  console.info(`Generated fixtures retained: ${root}`);
})();
